    @Test
    public void testACExprPrecedingExprFollowingClausePos() throws Exception {
        createModelsAndRun(
                () -> {
                    sink.clear();
                    try (SqlCompiler compiler = engine.getSqlCompiler()) {
                        for (String frameType : new String[]{"rows  ", "range "}) {
                            ExecutionModel model = compiler.generateExecutionModel(
                                    "select a,b, avg(c) over (partition by b order by ts #FRAME between 10 preceding and 5 preceding) from xyz".replace("#FRAME", frameType),
                                    sqlExecutionContext
                            );
                            ObjList<QueryColumn> columns = model.getQueryModel().getBottomUpColumns();
                            Assert.assertEquals(3, columns.size());

                            QueryColumn ac = columns.getQuick(2);
                            Assert.assertTrue(ac.isWindowExpression());
                            WindowExpression ac2 = (WindowExpression) ac;

                            // start of window expr position
                            Assert.assertEquals(67, ac2.getRowsLoExprPos());
                            Assert.assertEquals(70, ac2.getRowsLoKindPos());

                            // end of window expr position
                            Assert.assertEquals(84, ac2.getRowsHiExprPos());
                            Assert.assertEquals(86, ac2.getRowsHiKindPos());
                        }
                    }
                },
                modelOf("xyz")
                        .col("a", ColumnType.INT)
                        .col("b", ColumnType.INT)
                        .col("c", ColumnType.INT)
                        .timestamp("ts")
        );

    }

