    @Test
    public void testACExprPrecedingUnboundedFollowingExcludeTiesClause() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE xyz (a INT, b INT, c INT, ts TIMESTAMP) TIMESTAMP(ts)");
            assertQuery("select a,b, avg(c) over (partition by b order by ts rows between 1/1 preceding and unbounded following exclude ties) from xyz")
                    .noLeakCheck()
                    .fails(93, "frame end supports UNBOUNDED FOLLOWING only when frame start is UNBOUNDED PRECEDING");
            assertQuery("select a,b, avg(c) over (partition by b order by ts groups between 1/1 preceding and unbounded following exclude ties) from xyz")
                    .noLeakCheck()
                    .fails(95, "frame end supports UNBOUNDED FOLLOWING only when frame start is UNBOUNDED PRECEDING");
            assertQuery("select a,b, avg(c) over (partition by b order by ts range between 1/1 preceding and unbounded following exclude ties) from xyz")
                    .noLeakCheck()
                    .fails(94, "frame end supports UNBOUNDED FOLLOWING only when frame start is UNBOUNDED PRECEDING");
        });
    }

