    @Test
    public void testACRangeFrameAcceptsTimeUnits() throws Exception {
        final String[] units = {
                "microsecond",
                "microseconds",
                "millisecond",
                "milliseconds",
                "second",
                "seconds",
                "minute",
                "minutes",
                "hour",
                "hours",
                "day",
                "days"
        };
        final long[] precedingMicros = {
                10,
                10,
                10_000,
                10_000,
                10_000_000,
                10_000_000,
                600_000_000,
                600_000_000,
                36_000_000_000L,
                36_000_000_000L,
                864_000_000_000L,
                864_000_000_000L
        };
        assertMemoryLeak(() -> {
            execute("CREATE TABLE xyz (a INT, b INT, c INT, ts TIMESTAMP) TIMESTAMP(ts)");
            for (int i = 0; i < units.length; i++) {
                assertQuery("select a,b, avg(c) over (partition by b order by ts range 10 " + units[i] + " preceding) from xyz")
                        .noLeakCheck()
                        .assertsPlan(
                                "Window\n" +
                                        "  functions: [avg(c) over (partition by [b] range between " + precedingMicros[i] + " preceding and current row)]\n" +
                                        "    PageFrame\n" +
                                        "        Row forward scan\n" +
                                        "        Frame forward scan on: xyz\n"
                        );

                final String query = "select a,b, avg(c) over (partition by b order by ts range between 10 " + units[i] + " preceding and 1 " + units[i] + " following) from xyz";
                assertQuery(query)
                        .noLeakCheck()
                        .fails(query.indexOf("following"), "frame end supports _number_ PRECEDING and CURRENT ROW only");
            }
        });
    }

    @Test
    public void testACRangeRequiredOrderByOnNonDefaultFrameBoundaries() throws Exception {
        assertSyntaxError(
                "select a,b, f(c) over (partition by b range 1 preceding ) from xyz",
                38,
                "RANGE with offset PRECEDING/FOLLOWING requires exactly one ORDER BY column"
        );

        assertSyntaxError(
                "select a,b, f(c) over (partition by b range between 1 preceding and 1 following ) from xyz",
                38,
                "RANGE with offset PRECEDING/FOLLOWING requires exactly one ORDER BY column"
        );

        assertSyntaxError(
                "select a,b, f(c) over (partition by b range between unbounded preceding and 1 following ) from xyz",
                38,
                "RANGE with offset PRECEDING/FOLLOWING requires exactly one ORDER BY column"
        );
    }

