    @Test
    public void testBracedArithmeticsInsideCast() throws Exception {
        assertMemoryLeak(() -> {
            assertQuery("select cast((500000000000L + case when x > 400 then x - 1 else x end) as timestamp) ts from long_sequence(1000)")
                    .noLeakCheck()
                    .assertsPlan("""
                            VirtualRecord
                              functions: [500000000000L+case([400<x,x-1,x])::timestamp]
                                long_sequence count: 1000
                            """);
            assertColumnNames("select cast((500000000000L + case when x > 400 then x - 1 else x end) as timestamp) ts from long_sequence(1000)", "ts");
            assertQuery("select cast((500000000000L +   case when x > 400     then ((x - 1) / 4) * 1000L + (4 - (x - 1) % 4) * 89   else x end) as timestamp) ts from long_sequence(1000)")
                    .noLeakCheck()
                    .assertsPlan("""
                            VirtualRecord
                              functions: [500000000000L+case([400<x,x-1/4*1000L+4-x-1%4*89,x])::timestamp]
                                long_sequence count: 1000
                            """);
            assertColumnNames("select cast((500000000000L +   case when x > 400     then ((x - 1) / 4) * 1000L + (4 - (x - 1) % 4) * 89   else x end) as timestamp) ts from long_sequence(1000)", "ts");
            assertQuery("select (x - (1 - x)) as t1 from long_sequence(1000)")
                    .noLeakCheck()
                    .assertsPlan("""
                            VirtualRecord
                              functions: [x-1-x]
                                long_sequence count: 1000
                            """);
            assertColumnNames("select (x - (1 - x)) as t1 from long_sequence(1000)", "t1");
        });
    }

