    @Test
    public void testConsecutiveWindowJoins() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE trades (timestamp TIMESTAMP, tag SYMBOL, price DOUBLE) TIMESTAMP(timestamp)");
            execute("CREATE TABLE quotes (timestamp TIMESTAMP, tag SYMBOL, price DOUBLE) TIMESTAMP(timestamp)");
            assertQuery("select sum(q.price), sum(q1.price) from trades t WINDOW JOIN quotes q on tag range between 2 preceding and current row window join quotes q1 on tag range between 2 preceding and current row")
                    .noLeakCheck()
                    .assertsPlan("""
                            Window Fast Join
                              vectorized: false
                              symbol: t.tag=tag
                              window lo: 2 preceding (include prevailing)
                              window hi: current row
                                Async Window Fast Join workers: 1
                                  vectorized: true
                                  symbol: tag=tag
                                  window lo: 2 preceding (include prevailing)
                                  window hi: current row
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: trades
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: quotes
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: quotes
                            """);
            assertColumnNames("select sum(q.price), sum(q1.price) from trades t WINDOW JOIN quotes q on tag range between 2 preceding and current row window join quotes q1 on tag range between 2 preceding and current row", "sum", "sum1");
            assertQuery("select sum(t.price + q.price) from trades t asof JOIN quotes q on tag window join quotes q1 on tag range between 2 preceding and current row")
                    .noLeakCheck()
                    .assertsPlan("""
                            Window Fast Join
                              vectorized: false
                              symbol: t.tag=tag
                              window lo: 2 preceding (include prevailing)
                              window hi: current row
                                AsOf Join Fast
                                  condition: q.tag=t.tag
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: trades
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: quotes
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: quotes
                            """);
            assertColumnNames("select sum(t.price + q.price) from trades t asof JOIN quotes q on tag window join quotes q1 on tag range between 2 preceding and current row", "sum");
            assertQuery("select sum(t.price + q.price) from trades t WINDOW JOIN quotes q on tag range between 2 preceding and current row inner join quotes q1 on tag")
                    .noLeakCheck()
                    .fails(114, "no other join types allowed after window join");
        });
    }

