    @Test
    public void testCount() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE customers (customerId INT, customerName STRING)");
            execute("CREATE TABLE orders (customerId INT, product STRING)");
            assertQuery("select c.customerId, count() from customers c left join orders o on c.customerId = o.customerId  where o.customerId = NaN")
                    .noLeakCheck()
                    .assertsPlan("""
                            GroupBy vectorized: false
                              keys: [customerId]
                              values: [count(*)]
                                Filter filter: o.customerId=null
                                    Hash Left Outer Join Light
                                      condition: o.customerId=c.customerId
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: customers
                                        Hash
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: orders
                            """);
            assertColumnNames("select c.customerId, count() from customers c left join orders o on c.customerId = o.customerId  where o.customerId = NaN", "customerId", "count");
            assertQuery("select c.customerId, count() from customers c right join orders o on c.customerId = o.customerId  where o.customerId = NaN")
                    .noLeakCheck()
                    .assertsPlan("""
                            GroupBy vectorized: false
                              keys: [customerId]
                              values: [count(*)]
                                Filter filter: o.customerId=null
                                    Hash Right Outer Join Light
                                      condition: o.customerId=c.customerId
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: customers
                                        Hash
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: orders
                            """);
            assertColumnNames("select c.customerId, count() from customers c right join orders o on c.customerId = o.customerId  where o.customerId = NaN", "customerId", "count");
            assertQuery("select c.customerId, count() from customers c full join orders o on c.customerId = o.customerId  where o.customerId = NaN")
                    .noLeakCheck()
                    .assertsPlan("""
                            GroupBy vectorized: false
                              keys: [customerId]
                              values: [count(*)]
                                Filter filter: o.customerId=null
                                    Hash Full Outer Join Light
                                      condition: o.customerId=c.customerId
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: customers
                                        Hash
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: orders
                            """);
            assertColumnNames("select c.customerId, count() from customers c full join orders o on c.customerId = o.customerId  where o.customerId = NaN", "customerId", "count");
        });
    }

