    @Test
    public void testCrossJoinToInnerJoin() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE tab1 (x INT, y INT)");
            execute("CREATE TABLE tab2 (x INT, z INT)");
            assertQuery("select * from tab1 cross join tab2  where tab1.x = tab2.x")
                    .noLeakCheck()
                    .assertsPlan("""
                            SelectedRecord
                                Hash Join Light
                                  condition: tab2.x=tab1.x
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: tab1
                                    Hash
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: tab2
                            """);
            assertColumnNames("select * from tab1 cross join tab2  where tab1.x = tab2.x", "x", "y", "x1", "z");
        });
    }

    @Test
    public void testCrossJoinWithClause() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE customers (customerId INT, name STRING, age BYTE)");
            assertQuery("with cust as (customers where name ~ 'X') select * from cust c cross join cust c1 where c1.age = 30  limit 10")
                    .noLeakCheck()
                    .assertsPlan("""
                            Limit value: 10 skip-rows-max: 0 take-rows-max: 10
                                SelectedRecord
                                    Cross Join
                                        Async Filter workers: 1
                                          filter: name ~ X
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: customers
                                        Async Filter workers: 1
                                          filter: (name ~ X and age=30)
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: customers
                            """);
            assertColumnNames("with cust as (customers where name ~ 'X') select * from cust c cross join cust c1 where c1.age = 30  limit 10", "customerId", "name", "age", "customerId1", "name1", "age1");
        });
    }

    @Test
    public void testCteWithDoubleParensAndTimestampClauseSampleBy() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE trades (timestamp TIMESTAMP, amount DOUBLE) TIMESTAMP(timestamp)");
            assertQuery("WITH Test AS (( SELECT timestamp AS ts, amount FROM (  SELECT timestamp, amount FROM trades  WHERE timestamp IN '2024-03-08'  OR timestamp BETWEEN('2024-03-10T08:00:00Z', '2024-03-12') ) timestamp(timestamp))) SELECT ts, sum(amount) FROM Test SAMPLE BY 1d ALIGN TO CALENDAR TIME ZONE 'America/New_York'")
                    .noLeakCheck()
                    .assertsPlan("""
                            Sample By
                              fill: none
                              values: [sum(amount)]
                                SelectedRecord
                                    Async Filter workers: 1
                                      filter: (timestamp in [1709856000000000,1709942399999999] or timestamp between 1710057600000000 and 1710201600000000)
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: trades
                            """);
            assertColumnNames("WITH Test AS (( SELECT timestamp AS ts, amount FROM (  SELECT timestamp, amount FROM trades  WHERE timestamp IN '2024-03-08'  OR timestamp BETWEEN('2024-03-10T08:00:00Z', '2024-03-12') ) timestamp(timestamp))) SELECT ts, sum(amount) FROM Test SAMPLE BY 1d ALIGN TO CALENDAR TIME ZONE 'America/New_York'", "ts", "sum");
        });
    }

