    @Test
    public void testEqualsConstantTransitivityLhs() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE customers (customerId INT)");
            execute("CREATE TABLE orders (customerId INT)");
            final String query = "customers c" +
                    " #OUTER_JOIN_TYPE join orders o on c.customerId = o.customerId" +
                    " where 100 = c.customerId";
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "left"))
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Hash Left Outer Join Light
                                  condition: o.customerId=c.customerId
                                    Async JIT Filter workers: 1
                                      filter: 100=customerId
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: customers
                                    Hash
                                        Async JIT Filter workers: 1
                                          filter: customerId=100
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: orders
                            """)
                    .returns("customerId\tcustomerId1\n");
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "right"))
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Filter filter: 100=c.customerId
                                    Hash Right Outer Join Light
                                      condition: o.customerId=c.customerId
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: customers
                                        Hash
                                            Async JIT Filter workers: 1
                                              filter: customerId=100
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: orders
                            """)
                    .returns("customerId\tcustomerId1\n");
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "full"))
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Filter filter: 100=c.customerId
                                    Hash Full Outer Join Light
                                      condition: o.customerId=c.customerId
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: customers
                                        Hash
                                            Async JIT Filter workers: 1
                                              filter: customerId=100
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: orders
                            """)
                    .returns("customerId\tcustomerId1\n");
        });
    }

