    @Test
    public void testFilterOnSubQuery() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE customers (customerId INT, customerName STRING)");
            execute("CREATE TABLE orders (orderId INT, customerId INT)");
            final String query = "(select customerId, customerName, count() count from customers) c" +
                    " #OUTER_JOIN_TYPE join orders o on c.customerId = o.customerId " +
                    " where o.orderId = NaN and c.customerId > 400 and c.customerId < 1200 and count > 1 order by c.customerId";
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "left"))
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort
                              keys: [customerId]
                                SelectedRecord
                                    Filter filter: o.orderId=null
                                        Hash Left Outer Join Light
                                          condition: o.customerId=c.customerId
                                            Filter filter: 1<count
                                                Async JIT Group By workers: 1
                                                  keys: [customerId,customerName]
                                                  values: [count(*)]
                                                  filter: (400<customerId and customerId<1200)
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: customers
                                            Hash
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: orders
                            """)
                    .returns("customerId\tcustomerName\tcount\torderId\tcustomerId1\n");
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "right"))
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort
                              keys: [customerId]
                                SelectedRecord
                                    Filter filter: (o.orderId=null and 400<c.customerId and c.customerId<1200 and 1<c.count)
                                        Hash Right Outer Join Light
                                          condition: o.customerId=c.customerId
                                            Async Group By workers: 1
                                              keys: [customerId,customerName]
                                              values: [count(*)]
                                              filter: null
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: customers
                                            Hash
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: orders
                            """)
                    .returns("customerId\tcustomerName\tcount\torderId\tcustomerId1\n");
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "full"))
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort
                              keys: [customerId]
                                SelectedRecord
                                    Filter filter: (o.orderId=null and 400<c.customerId and c.customerId<1200 and 1<c.count)
                                        Hash Full Outer Join Light
                                          condition: o.customerId=c.customerId
                                            Async Group By workers: 1
                                              keys: [customerId,customerName]
                                              values: [count(*)]
                                              filter: null
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: customers
                                            Hash
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: orders
                            """)
                    .returns("customerId\tcustomerName\tcount\torderId\tcustomerId1\n");
        });
    }

