    @Test
    public void testGroupByAliasExistsInProjection() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE trades (symbol SYMBOL, side SYMBOL, price DOUBLE, amount DOUBLE, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            assertQuery(
                    """
                            WITH
                              offsets AS (
                                SELECT offs*100000 AS usec_offs, offs
                                FROM (
                                  SELECT (x-51) AS offs
                                  FROM long_sequence(101)
                                )
                              ),
                              orders AS (
                                SELECT * \s
                                FROM trades
                                WHERE timestamp IN '2025-05-21'
                                LIMIT 10
                              ),
                              points AS (
                                SELECT orders.*, offsets.usec_offs*0.001 AS msec_offs, offs, timestamp + usec_offs AS tsXYZ
                                FROM orders CROSS JOIN offsets
                                ORDER BY tsXYZ ASC
                              )
                            select * from points;"""
            )
                    .noLeakCheck()
                    .timestamp("tsXYZ")
                    .withPlan("""
                            Encode sort
                              keys: [tsXYZ]
                                VirtualRecord
                                  functions: [orders.symbol,orders.side,orders.price,orders.amount,orders.timestamp,offsets.usec_offs*0.001,offsets.offs,orders.timestamp+offsets.usec_offs]
                                    Cross Join
                                        Limit value: 10 skip-rows-max: 0 take-rows-max: 10
                                            PageFrame
                                                Row forward scan
                                                Interval forward scan on: trades
                                                  intervals: [("2025-05-21T00:00:00.000000Z","2025-05-21T23:59:59.999999Z")]
                                        VirtualRecord
                                          functions: [offs*100000,offs]
                                            VirtualRecord
                                              functions: [x-51]
                                                long_sequence count: 101
                            """)
                    .returns("symbol\tside\tprice\tamount\ttimestamp\tmsec_offs\toffs\ttsXYZ\n");
        });
    }

