    @Test
    public void testHints() throws Exception {
        assertMemoryLeak(() -> {
            // simple smoke test
            execute("CREATE TABLE xyz (a SYMBOL, b INT, c INT)");
            assertQuery("select /*+ NO_INDEX(a) NEW_HINT(a b) NO_PARAM_HINT*/ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // empty hints
            assertQuery("select /*+ */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // hint nested inside outer comment is ignored
            assertQuery("select /* /*+ NO_INDEX(a) */ */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // hint nested in a line comment is ignored
            assertQuery("select -- /*+ NO_INDEX(a) */ \n a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // hints nested inside another hint are ignored
            assertQuery("select /*+ NO_INDEX(a) /*+ IGNORED */ */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // comment nested inside hint is ignored
            assertQuery("select /*+ NO_INDEX(a) /* THIS IS JUST A REGULAR COMMENT */ AFTER */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // line comment inside hints are honoured
            assertQuery("select /*+ NO_INDEX(a) -- IGNORED \n */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // bad hint syntax - missing closing bracket
            assertQuery("select /*+ NO_INDEX(a) SKIPPED(  */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // bad hint syntax - missing opening brackets
            assertQuery("select /*+ NO_INDEX(a) SKIPPED)  */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // bad hint syntax - missing hint key
            assertQuery("select /*+ NO_INDEX(a) (param)  */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // nested params
            assertQuery("select /*+ NO_INDEX(a) SKIPPED(a (b))  */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // empty params
            assertQuery("select /*+ NO_INDEX()  */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // consecutive parameter-free hints
            assertQuery("select /*+ NO_INDEX MAKE_IT_FAST  */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // quoted hint name is NOT unquoted!
            assertQuery("select /*+ \"NO_INDEX\"  */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // quoted param - params are unquoted!
            assertQuery("select /*+ NO_INDEX(\"a\")  */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // dangling quotes in parameter less hint name - we still parse the hint which is right prior to the dangling quote
            assertQuery("select /*+ NO_INDEX(a) NOT_SKIPPED\" */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // dangling quote in parameter 1 - right after the opening parenthesis
            assertQuery("select /*+ NO_INDEX(a) SKIPPED(\"foo) */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // dangling quote in parameter
            assertQuery("select /*+ NO_INDEX(a) SKIPPED(foo\") */ a,b,c from xyz where a = 1")
                    .noLeakCheck()
                    .withPlan("""
                            Async JIT Filter workers: 1
                              filter: a='1'
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // model with joins
            execute("CREATE TABLE trades (timestamp TIMESTAMP, tag SYMBOL) TIMESTAMP(timestamp)");
            execute("CREATE TABLE quotes (timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            assertQuery("select /*+ HINT*/ * from trades t ASOF JOIN quotes q WHERE tag = null")
                    .noLeakCheck()
                    .timestamp("timestamp")
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                AsOf Join Fast
                                    Async JIT Filter workers: 1
                                      filter: tag is null
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: trades
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: quotes
                            """)
                    .returns("timestamp\ttag\ttimestamp1\n");
            // model with sample by - simple
            assertQuery("select /*+ HINT*/ timestamp, count(*) from trades sample by 1d")
                    .noLeakCheck()
                    .timestamp("timestamp")
                    .withPlan("""
                            Encode sort light
                              keys: [timestamp]
                                Async Group By workers: 1
                                  keys: [timestamp]
                                  keyFunctions: [timestamp_floor_utc('1d',timestamp)]
                                  values: [count(*)]
                                  filter: null
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: trades
                            """)
                    .returns("timestamp\tcount\n");
            // model with sample by - with projection
            // todo: hints currently do not appear in the outer SELECT-CHOOSE, consider adding them?
            assertQuery("select /*+ HINT*/ tag, count(*) from trades sample by 1d")
                    .noLeakCheck()
                    .withPlan("""
                            SelectedRecord
                                Encode sort light
                                  keys: [timestamp]
                                    Async Group By workers: 1
                                      keys: [tag,timestamp]
                                      keyFunctions: [timestamp_floor_utc('1d',timestamp)]
                                      values: [count(*)]
                                      filter: null
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: trades
                            """)
                    .returns("tag\tcount\n");
            // model with union
            assertQuery("select /*+ HINT_A*/ a,b,c from xyz where a = 1 union select /*+ HINT_B*/ a,b,c from xyz where a = 2")
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            UnionSymbolCast
                              functions: [a::symbol,b,c]
                                Union
                                    Async JIT Filter workers: 1
                                      filter: a='1'
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: xyz
                                    Async JIT Filter workers: 1
                                      filter: a='2'
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: xyz
                            """)
                    .returns("a\tb\tc\n");
            // ending with unclosed hint - it reports missing columns instead of missing closing comment
            // this behaviour is consistent with a regular block comments unclosed, except for position
            assertSyntaxError(
                    "select /*+ HINT_A",
                    17,
                    "[distinct] column expected"
            );
            // for a comparison: here the same error with regular (non-hint) comments
            assertSyntaxError(
                    "select /* HINT_A",
                    7,
                    "[distinct] column expected"
            );
        });
    }

