    @Test
    public void testHorizonJoinMultiNoRangeOrListOnAny() throws Exception {
        assertSyntaxError(
                "SELECT avg(b.bid) FROM trades AS t HORIZON JOIN bids AS b ON (t.sym = b.sym) HORIZON JOIN asks AS a ON (t.sym = a.sym)",
                35,
                "HORIZON JOIN requires offset configuration (RANGE or LIST)",
                modelOf("trades").col("sym", ColumnType.SYMBOL).timestamp(),
                modelOf("bids").col("sym", ColumnType.SYMBOL).col("bid", ColumnType.DOUBLE).timestamp(),
                modelOf("asks").col("sym", ColumnType.SYMBOL).col("ask", ColumnType.DOUBLE).timestamp()
        );
    }

    @Test
    public void testHorizonJoinMultiNonHorizonAfterHorizon() throws Exception {
        assertSyntaxError(
                "SELECT avg(p.price) FROM trades AS t HORIZON JOIN bids AS b ON (t.sym = b.sym) ASOF JOIN prices AS p ON (t.sym = p.sym) LIST (0s) AS h",
                79,
                "only horizon joins can follow a horizon join",
                modelOf("trades").col("sym", ColumnType.SYMBOL).timestamp(),
                modelOf("bids").col("sym", ColumnType.SYMBOL).col("bid", ColumnType.DOUBLE).timestamp(),
                modelOf("prices").col("sym", ColumnType.SYMBOL).col("price", ColumnType.DOUBLE).timestamp()
        );
    }

    @Test
    public void testHorizonJoinMultiThreeSlavesList() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE trades (sym SYMBOL, qty DOUBLE, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            execute("CREATE TABLE bids (sym SYMBOL, bid DOUBLE, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            execute("CREATE TABLE asks (sym SYMBOL, ask DOUBLE, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            execute("CREATE TABLE mids (sym SYMBOL, mid DOUBLE, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            assertQuery("SELECT avg(b.bid) AS avg_bid, avg(a.ask) AS avg_ask, avg(m.mid) AS avg_mid FROM trades AS t HORIZON JOIN bids AS b ON (t.sym = b.sym) HORIZON JOIN asks AS a ON (t.sym = a.sym) HORIZON JOIN mids AS m ON (t.sym = m.sym) LIST (0s) AS h")
                    .noLeakCheck()
                    .noRandomAccess()
                    .expectSize()
                    .withPlan("""
                            Async Multi Horizon Join workers: 1 offsets: 1 tables: 3
                              values: [avg(b.bid),avg(a.ask),avg(m.mid)]
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: trades
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: bids
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: asks
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: mids
                            """)
                    .returns("""
                            avg_bid\tavg_ask\tavg_mid
                            null\tnull\tnull
                            """);
        });
    }

