    @Test
    public void testInnerJoinPostFilter() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE x (c INT, a INT)");
            execute("CREATE TABLE y (m INT, b INT)");
            execute("CREATE TABLE z (c INT, d INT)");
            assertQuery("select z.c, x.a, b, d, d-b from x join y on y.m = x.c join z on (c) where y.b < 20")
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            VirtualRecord
                              functions: [z.c,x.a,y.b,z.d,z.d-y.b]
                                Hash Join Light
                                  condition: z.c=x.c
                                    Hash Join Light
                                      condition: y.m=x.c
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: x
                                        Hash
                                            Async JIT Filter workers: 1
                                              filter: b<20
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: y
                                    Hash
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: z
                            """)
                    .returns("c\ta\tb\td\tcolumn\n");
        });
    }

    @Test
    public void testInnerJoinSubQuery() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE customers (customerId INT, customerName STRING)");
            execute("CREATE TABLE orders (customerId INT, productName STRING, productId INT, orderId INT)");
            execute("CREATE TABLE products (productId INT)");
            assertQuery(
                    "select customerName, productName, orderId from (" +
                            "select \"customerName\", orderId, productId, productName " +
                            "from \"customers\" join orders on \"customers\".\"customerId\" = orders.customerId where productName ~ 'WTBHZVPVZZ'" +
                            ") x" +
                            " join products p on p.productId = x.productId"
            )
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Hash Join Light
                                  condition: p.productId=x.productId
                                    SelectedRecord
                                        Hash Join Light
                                          condition: orders.customerId=customers.customerId
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: customers
                                            Hash
                                                Async Filter workers: 1
                                                  filter: productName ~ WTBHZVPVZZ
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: orders
                                    Hash
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: products
                            """)
                    .returns("customerName\tproductName\torderId\n");
            assertQuery(
                    "select customerName, productName, orderId " +
                            " from customers join orders o on customers.customerId = o.customerId " +
                            " join products p on p.productId = o.productId" +
                            " where productName ~ 'WTBHZVPVZZ'"
            )
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Hash Join Light
                                  condition: p.productId=o.productId
                                    Hash Join Light
                                      condition: o.customerId=customers.customerId
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: customers
                                        Hash
                                            Async Filter workers: 1
                                              filter: productName ~ WTBHZVPVZZ
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: orders
                                    Hash
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: products
                            """)
                    .returns("customerName\tproductName\torderId\n");
        });
    }

    @Test
    public void testInsertAsSelect() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE x (a INT, b STRING)");
            execute("CREATE TABLE y (c INT, d STRING)");
            execute("INSERT INTO y VALUES (1, 'foo'), (2, 'bar')");
            execute("insert atomic into x select * from y");
            assertQuery("x")
                    .noLeakCheck()
                    .expectSize()
                    .returns("""
                            a\tb
                            1\tfoo
                            2\tbar
                            """);
        });
    }

