    @Test
    public void testJoin1() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE tab (ts TIMESTAMP, x INT) TIMESTAMP(ts)");
            execute("CREATE TABLE tab2 (x INT)");
            execute("CREATE TABLE tab3 (b INT)");
            execute("CREATE TABLE tab4 (ts TIMESTAMP, x INT, y INT, z INT, a INT, b INT) TIMESTAMP(ts)");
            assertQuery(
                    "select t1.x, y from (select x from tab t2 where x > 100 latest on ts partition by x) t1 " +
                            "join tab2 xx2 on xx2.x = t1.x " +
                            "join tab3 on xx2.x > tab3.b " +
                            "join (select x,y from tab4 where a > b latest on ts partition by z) x4 on x4.x = t1.x " +
                            "where y > 0"
            )
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Filter filter: tab3.b<xx2.x
                                    Cross Join
                                        Hash Join Light
                                          condition: x4.x=t1.x
                                            Hash Join Light
                                              condition: xx2.x=t1.x
                                                LatestByAllFiltered
                                                    Row backward scan
                                                      filter: 100<x
                                                    Frame backward scan on: tab
                                                Hash
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: tab2
                                            Hash
                                                SelectedRecord
                                                    Filter filter: 0<y
                                                        LatestByAllFiltered
                                                            Row backward scan
                                                              filter: b<a
                                                            Frame backward scan on: tab4
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: tab3
                            """)
                    .returns("x\ty\n");
        });
    }

    @Test
    public void testJoin3() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE tab (x INT)");
            execute("CREATE TABLE tab2 (x INT)");
            execute("CREATE TABLE tab3 (x INT)");
            assertQuery("select x from (select tab2.x from tab join tab2 on tab.x=tab2.x join tab3 on greatest(tab3.x,tab2.x) = tab.x)")
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Filter filter: greatest[LONG]([tab3.x,tab2.x])::int=tab.x
                                    Cross Join
                                        Hash Join Light
                                          condition: tab2.x=tab.x
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: tab
                                            Hash
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: tab2
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: tab3
                            """)
                    .returns("x\n");
        });
    }

    @Test
    public void testJoinClauseAlignmentBug() throws Exception {
        assertMemoryLeak(() -> {
            final String query = """
                    SELECT\s
                         NULL AS TABLE_CAT,\s
                         n.nspname AS TABLE_SCHEM,\s
                        \s
                         c.relname AS TABLE_NAME, \s
                         CASE n.nspname ~ '^pg_' OR n.nspname = 'information_schema' \s
                            WHEN true THEN\s
                               CASE \s
                                    WHEN n.nspname = 'pg_catalog' OR n.nspname = 'information_schema' THEN\s
                                        CASE c.relkind  \s
                                            WHEN 'r' THEN 'SYSTEM TABLE'\s
                                            WHEN 'v' THEN 'SYSTEM VIEW'
                                            WHEN 'i' THEN 'SYSTEM INDEX'
                                            ELSE NULL  \s
                                        END
                                    WHEN n.nspname = 'pg_toast' THEN\s
                                        CASE c.relkind  \s
                                            WHEN 'r' THEN 'SYSTEM TOAST TABLE'
                                            WHEN 'i' THEN 'SYSTEM TOAST INDEX'
                                            ELSE NULL  \s
                                        END
                                    ELSE\s
                                        CASE c.relkind
                                            WHEN 'r' THEN 'TEMPORARY TABLE'
                                            WHEN 'p' THEN 'TEMPORARY TABLE'
                                            WHEN 'i' THEN 'TEMPORARY INDEX'
                                            WHEN 'S' THEN 'TEMPORARY SEQUENCE'
                                            WHEN 'v' THEN 'TEMPORARY VIEW'
                                            ELSE NULL  \s
                                        END \s
                                END \s
                            WHEN false THEN\s
                                CASE c.relkind \s
                                    WHEN 'r' THEN 'TABLE' \s
                                    WHEN 'p' THEN 'PARTITIONED TABLE' \s
                                    WHEN 'i' THEN 'INDEX' \s
                                    WHEN 'S' THEN 'SEQUENCE' \s
                                    WHEN 'v' THEN 'VIEW' \s
                                    WHEN 'c' THEN 'TYPE' \s
                                    WHEN 'f' THEN 'FOREIGN TABLE' \s
                                    WHEN 'm' THEN 'MATERIALIZED VIEW' \s
                                    ELSE NULL \s
                                END \s
                            ELSE NULL \s
                        END AS TABLE_TYPE,\s
                        d.description AS REMARKS,
                        '' as TYPE_CAT,
                        '' as TYPE_SCHEM,
                        '' as TYPE_NAME,
                        '' AS SELF_REFERENCING_COL_NAME,
                        '' AS REF_GENERATION
                    FROM\s
                        pg_catalog.pg_namespace n,\s
                        pg_catalog.pg_class c \s
                        #OUTER_JOIN_TYPE join pg_catalog.pg_description d ON (c.oid = d.objoid AND d.objsubid = 0)\s
                        #OUTER_JOIN_TYPE join pg_catalog.pg_class dc ON (d.classoid=dc.oid AND dc.relname='pg_class')
                        #OUTER_JOIN_TYPE join pg_catalog.pg_namespace dn ON (dn.oid=dc.relnamespace AND dn.nspname='pg_catalog')
                    WHERE\s
                        c.relnamespace = n.oid \s
                        AND c.relname LIKE 'quickstart-events2'\s
                        AND (
                            false \s
                            OR  ( c.relkind = 'r' AND n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' )\s
                            )\s
                    ORDER BY TABLE_TYPE,TABLE_SCHEM,TABLE_NAME""";
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "left"))
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort
                              keys: [TABLE_TYPE, TABLE_SCHEM, TABLE_NAME]
                                VirtualRecord
                                  functions: [null,n.nspname,c.relname,case([(n.nspname ~ ^pg_ or n.nspname='information_schema'),case([(n.nspname='pg_catalog' or n.nspname='information_schema'),case(['SYSTEM TABLE','SYSTEM VIEW','SYSTEM INDEX',null,c.relkind]),n.nspname='pg_toast',case(['SYSTEM TOAST TABLE','SYSTEM TOAST INDEX',null,c.relkind]),case(['TEMPORARY TABLE','TEMPORARY TABLE','TEMPORARY INDEX','TEMPORARY SEQUENCE','TEMPORARY VIEW',null,c.relkind])]),case(['TABLE','PARTITIONED TABLE','INDEX','SEQUENCE','VIEW','TYPE','FOREIGN TABLE','MATERIALIZED VIEW',null,c.relkind])]),d.description,'','','','','']
                                    Hash Left Outer Join
                                      condition: dn.oid=dc.relnamespace
                                      filter: dn.nspname='pg_catalog'
                                        Hash Left Outer Join
                                          condition: dc.oid=d.classoid
                                          filter: dc.relname='pg_class'
                                            Hash Left Outer Join Light
                                              condition: d.objoid=c.oid
                                              filter: d.objsubid=0
                                                Hash Join
                                                  condition: c.relnamespace=n.oid
                                                    Filter filter: (nspname !~ ^pg_ and nspname!='information_schema')
                                                        GenericRecord
                                                    Hash
                                                        Filter filter: (relname ~ quickstart-events2 and relkind=r)
                                                            pg_class
                                                Hash
                                                    Empty table
                                            Hash
                                                pg_class
                                        Hash
                                            GenericRecord
                            """)
                    .returns("TABLE_CAT\tTABLE_SCHEM\tTABLE_NAME\tTABLE_TYPE\tREMARKS\tTYPE_CAT\tTYPE_SCHEM\tTYPE_NAME\tSELF_REFERENCING_COL_NAME\tREF_GENERATION\n");
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "right"))
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort
                              keys: [TABLE_TYPE, TABLE_SCHEM, TABLE_NAME]
                                VirtualRecord
                                  functions: [null,n.nspname,c.relname,case([(n.nspname ~ ^pg_ or n.nspname='information_schema'),case([(n.nspname='pg_catalog' or n.nspname='information_schema'),case(['SYSTEM TABLE','SYSTEM VIEW','SYSTEM INDEX',null,c.relkind]),n.nspname='pg_toast',case(['SYSTEM TOAST TABLE','SYSTEM TOAST INDEX',null,c.relkind]),case(['TEMPORARY TABLE','TEMPORARY TABLE','TEMPORARY INDEX','TEMPORARY SEQUENCE','TEMPORARY VIEW',null,c.relkind])]),case(['TABLE','PARTITIONED TABLE','INDEX','SEQUENCE','VIEW','TYPE','FOREIGN TABLE','MATERIALIZED VIEW',null,c.relkind])]),d.description,'','','','','']
                                    Filter filter: (c.relnamespace=n.oid and c.relkind=r)
                                        Cross Join
                                            Filter filter: c.relname ~ quickstart-events2
                                                Hash Right Outer Join
                                                  condition: dn.oid=dc.relnamespace
                                                  filter: dn.nspname='pg_catalog'
                                                    Hash Right Outer Join
                                                      condition: dc.oid=d.classoid
                                                      filter: dc.relname='pg_class'
                                                        Hash Right Outer Join Light
                                                          condition: d.objoid=c.oid
                                                          filter: d.objsubid=0
                                                            pg_class
                                                            Hash
                                                                Empty table
                                                        Hash
                                                            pg_class
                                                    Hash
                                                        GenericRecord
                                            Filter filter: (nspname !~ ^pg_ and nspname!='information_schema')
                                                GenericRecord
                            """)
                    .returns("TABLE_CAT\tTABLE_SCHEM\tTABLE_NAME\tTABLE_TYPE\tREMARKS\tTYPE_CAT\tTYPE_SCHEM\tTYPE_NAME\tSELF_REFERENCING_COL_NAME\tREF_GENERATION\n");
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "full"))
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort
                              keys: [TABLE_TYPE, TABLE_SCHEM, TABLE_NAME]
                                VirtualRecord
                                  functions: [null,n.nspname,c.relname,case([(n.nspname ~ ^pg_ or n.nspname='information_schema'),case([(n.nspname='pg_catalog' or n.nspname='information_schema'),case(['SYSTEM TABLE','SYSTEM VIEW','SYSTEM INDEX',null,c.relkind]),n.nspname='pg_toast',case(['SYSTEM TOAST TABLE','SYSTEM TOAST INDEX',null,c.relkind]),case(['TEMPORARY TABLE','TEMPORARY TABLE','TEMPORARY INDEX','TEMPORARY SEQUENCE','TEMPORARY VIEW',null,c.relkind])]),case(['TABLE','PARTITIONED TABLE','INDEX','SEQUENCE','VIEW','TYPE','FOREIGN TABLE','MATERIALIZED VIEW',null,c.relkind])]),d.description,'','','','','']
                                    Filter filter: (c.relnamespace=n.oid and c.relkind=r)
                                        Cross Join
                                            Filter filter: c.relname ~ quickstart-events2
                                                Hash Full Outer Join
                                                  condition: dn.oid=dc.relnamespace
                                                  filter: dn.nspname='pg_catalog'
                                                    Hash Full Outer Join
                                                      condition: dc.oid=d.classoid
                                                      filter: dc.relname='pg_class'
                                                        Hash Full Outer Join Light
                                                          condition: d.objoid=c.oid
                                                          filter: d.objsubid=0
                                                            pg_class
                                                            Hash
                                                                Empty table
                                                        Hash
                                                            pg_class
                                                    Hash
                                                        GenericRecord
                                            Filter filter: (nspname !~ ^pg_ and nspname!='information_schema')
                                                GenericRecord
                            """)
                    .returns("TABLE_CAT\tTABLE_SCHEM\tTABLE_NAME\tTABLE_TYPE\tREMARKS\tTYPE_CAT\tTYPE_SCHEM\tTYPE_NAME\tSELF_REFERENCING_COL_NAME\tREF_GENERATION\n");
        });
    }

    @Test
    public void testJoinColumnPropagation() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE sensors (ID LONG, make STRING, city STRING)");
            execute("CREATE TABLE readings (ID LONG, ts TIMESTAMP, temp DOUBLE, sensorId LONG) TIMESTAMP(ts)");
            assertQuery(
                    """
                            SELECT city, max(temp)
                            FROM readings
                            JOIN(
                                SELECT ID sensId, city
                                FROM sensors)
                            ON readings.sensorId = sensId"""
            )
                    .noLeakCheck()
                    .withPlan("""
                            GroupBy vectorized: false
                              keys: [city]
                              values: [max(readings.temp)]
                                Hash Join Light
                                  condition: sensId=readings.sensorId
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: readings
                                    Hash
                                        SelectedRecord
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: sensors
                            """)
                    .returns("city\tmax\n");
        });
    }

    @Test
    public void testJoinColumnResolutionOnSubQuery() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE x (ccy SYMBOL)");
            execute("CREATE TABLE y (ccy SYMBOL, timestamp TIMESTAMP)");
            assertQuery("select sum(timestamp) from (select * from y) cross join (x)")
                    .noLeakCheck()
                    .noRandomAccess()
                    .expectSize()
                    .withPlan("""
                            GroupBy vectorized: false
                              values: [sum(_xQdbA1.timestamp)]
                                Cross Join
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: y
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: x
                            """)
                    .returns("""
                            sum
                            null
                            """);
        });
    }

