    @Test
    public void testJoinTimestampPropagation() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE telemetry_users (id LONG256, created TIMESTAMP, event SHORT, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            assertQuery(
                    """
                            with\s
                                starts as ((telemetry_users where event = 100 order by created) timestamp(created)),
                                stops as ((telemetry_users where event = 101 order by created) timestamp(created))
                            
                            select * from (select a.created ts_stop, a.id, b.created ts_start, b.id from stops a lt join starts b on (id)) where id <> '0x05ab1e873d165b00000005743f2c17' and ts_stop - ts_start > 10000000000
                            """
            )
                    .noLeakCheck()
                    .timestamp("ts_stop")
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Filter filter: 10000000000L<a.created-b.created
                                    Lt Join Light
                                      condition: b.id=a.id
                                        Encode sort light
                                          keys: [created]
                                            SelectedRecord
                                                Async Filter workers: 1
                                                  filter: (event=101 and id!=0x05ab1e873d165b00000005743f2c17)
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: telemetry_users
                                        Encode sort light
                                          keys: [created]
                                            SelectedRecord
                                                Async JIT Filter workers: 1
                                                  filter: event=100
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: telemetry_users
                            """)
                    .returns("ts_stop\tid\tts_start\tid1\n");
        });
    }

