    @Test
    public void testJoinWithFilter() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE orders (orderId INT)");
            execute("CREATE TABLE customers (customerId INT)");
            execute("CREATE TABLE orderDetails (orderId INT, productId INT, quantity DOUBLE)");
            execute("CREATE TABLE products (productId INT, supplier INT, price DOUBLE)");
            execute("CREATE TABLE suppliers (supplier INT)");
            assertQuery(
                    "customers" +
                            " cross join orders" +
                            " join orderDetails d on d.orderId = orders.orderId and d.productId = customers.customerId" +
                            " join products on d.productId = products.productId" +
                            " join suppliers on products.supplier = suppliers.supplier" +
                            " where d.productId = d.orderId" +
                            " and (products.price > d.quantity or d.orderId = orders.orderId) and d.quantity < orders.orderId"
            )
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Hash Join Light
                                  condition: suppliers.supplier=products.supplier
                                    Filter filter: (d.quantity<products.price or d.orderId=orders.orderId)
                                        Hash Join Light
                                          condition: products.productId=d.productId
                                            Filter filter: d.quantity<orders.orderId
                                                Hash Join Light
                                                  condition: orders.orderId=d.orderId
                                                    Hash Join Light
                                                      condition: d.productId=customers.customerId
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: customers
                                                        Hash
                                                            Async JIT Filter workers: 1
                                                              filter: productId=orderId
                                                                PageFrame
                                                                    Row forward scan
                                                                    Frame forward scan on: orderDetails
                                                    Hash
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: orders
                                            Hash
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: products
                                    Hash
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: suppliers
                            """)
                    .returns("customerId\torderId\torderId1\tproductId\tquantity\tproductId1\tsupplier\tprice\tsupplier1\n");
        });
    }

