    @Test
    public void testNestedJoinReorder() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE orders (orderId INT, customerId INT)");
            execute("CREATE TABLE customers (customerId INT)");
            execute("CREATE TABLE orderDetails (orderId INT, productId INT)");
            execute("CREATE TABLE products (productId INT, supplier INT)");
            execute("CREATE TABLE suppliers (supplier INT)");
            execute("CREATE TABLE shippers (shipper INT)");
            assertQuery(
                    "with x as (select orders.orderId, products.productId from " +
                            "orders" +
                            " join orderDetails d on d.orderId = orders.orderId and d.orderId = customers.customerId" +
                            " join customers on orders.customerId = customers.customerId" +
                            " join products on d.productId = products.productId" +
                            " join suppliers on products.supplier = suppliers.supplier" +
                            " where d.productId = d.orderId), " +
                            " y as (" +
                            "orders" +
                            " join customers on orders.customerId = customers.customerId" +
                            " join orderDetails d on d.orderId = orders.orderId and orders.orderId = products.productId" +
                            " join suppliers on products.supplier = suppliers.supplier" +
                            " join products on d.productId = products.productId and orders.orderId = products.productId" +
                            " where orders.orderId = suppliers.supplier)" +
                            " select * from x cross join y"
            )
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Cross Join
                                    SelectedRecord
                                        Hash Join Light
                                          condition: suppliers.supplier=products.supplier
                                            Hash Join Light
                                              condition: products.productId=d.productId
                                                Hash Join Light
                                                  condition: customers.customerId=orders.customerId
                                                    Hash Join Light
                                                      condition: d.orderId=orders.customerId
                                                        Async JIT Filter workers: 1
                                                          filter: orderId=customerId
                                                            PageFrame
                                                                Row forward scan
                                                                Frame forward scan on: orders
                                                        Hash
                                                            Async JIT Filter workers: 1
                                                              filter: productId=orderId
                                                                PageFrame
                                                                    Row forward scan
                                                                    Frame forward scan on: orderDetails
                                                    Hash
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: customers
                                                Hash
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: products
                                            Hash
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: suppliers
                                    SelectedRecord
                                        Hash Join Light
                                          condition: products.productId=orders.orderId and products.supplier=suppliers.supplier
                                            Hash Join Light
                                              condition: suppliers.supplier=orders.orderId
                                                Hash Join Light
                                                  condition: d.productId=orders.orderId
                                                    Hash Join Light
                                                      condition: customers.customerId=orders.customerId
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: orders
                                                        Hash
                                                            PageFrame
                                                                Row forward scan
                                                                Frame forward scan on: customers
                                                    Hash
                                                        Async JIT Filter workers: 1
                                                          filter: orderId=productId
                                                            PageFrame
                                                                Row forward scan
                                                                Frame forward scan on: orderDetails
                                                Hash
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: suppliers
                                            Hash
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: products
                            """)
                    .returns("orderId\tproductId\torderId1\tcustomerId\tcustomerId1\torderId11\tproductId1\tsupplier\tproductId11\tsupplier1\n");
        });
    }

    @Test
    public void testNestedSubQueryParseErrorIsPositioned() throws Exception {
        // A parse error inside a sub-query nested two lambda levels deep throws from a parseExpr
        // frame whose scope-stack bottom was raised by the enclosing lambdas. The error-unwind path
        // used to restore that stale bottom over an already-cleared stack and leak an internal
        // "Tried to set bottom beyond the top of the stack" IllegalStateException, masking the real
        // positioned error. The user must still see the original syntax error.
        assertSyntaxError(
                "select * from x where a in " +
                        "(select a from x where a in " +
                        "(select a from x where b > ))",
                80,
                "too few arguments for '>'",
                modelOf("x").col("a", ColumnType.SYMBOL).col("b", ColumnType.INT)
        );
    }

    @Test
    public void testNestedWindowFrameParseErrorIsPositioned() throws Exception {
        // The window-expression sibling of testNestedSubQueryParseErrorIsPositioned. A parse error in
        // a window frame bound, nested inside a lambda sub-query, unwinds through parseWindowExpr's
        // finally, which restores the op/paramCount/argStackDepth bottoms raised by the enclosing
        // lambda. Without the clamp those restores ran over the already-cleared stacks and leaked an
        // internal "Tried to set bottom beyond the top of the stack" IllegalStateException, masking
        // the real positioned error. The user must still see the original syntax error.
        assertSyntaxError(
                "select * from t where a in " +
                        "(select sum(a) over (order by y rows between (a + ) preceding and current row) from t)",
                75,
                "too few arguments for '+'",
                modelOf("t").col("a", ColumnType.INT).col("y", ColumnType.LONG)
        );
    }

    @Test
    public void testNonAggFunctionWithAggFunctionSampleBy() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE xetra (ts TIMESTAMP, isin SYMBOL, start_price DOUBLE) TIMESTAMP(ts)");
            assertQuery("select day(ts), isin, last(start_price) from xetra where isin='DE000A0KRJS4' sample by 1d align to first observation")
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            VirtualRecord
                              functions: [day(ts),isin,last]
                                Sample By
                                  keys: [ts,isin]
                                  values: [last(start_price)]
                                    Async JIT Filter workers: 1
                                      filter: isin='DE000A0KRJS4'
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: xetra
                            """)
                    .returns("day\tisin\tlast\n");
            assertQuery("select day(ts), isin, last(start_price) from xetra where isin='DE000A0KRJS4' sample by 1d")
                    .noLeakCheck()
                    .withPlan("""
                            SelectedRecord
                                Encode sort light
                                  keys: [ts]
                                    VirtualRecord
                                      functions: [day(ts),isin,last,ts]
                                        Async JIT Group By workers: 1
                                          keys: [ts,isin]
                                          keyFunctions: [timestamp_floor_utc('1d',ts)]
                                          values: [last(start_price)]
                                          filter: isin='DE000A0KRJS4'
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: xetra
                            """)
                    .returns("day\tisin\tlast\n");
            assertQuery("select day(ts), isin, last(start_price) from xetra where isin='DE000A0KRJS4' sample by 1d align to calendar")
                    .noLeakCheck()
                    .withPlan("""
                            SelectedRecord
                                Encode sort light
                                  keys: [ts]
                                    VirtualRecord
                                      functions: [day(ts),isin,last,ts]
                                        Async JIT Group By workers: 1
                                          keys: [ts,isin]
                                          keyFunctions: [timestamp_floor_utc('1d',ts)]
                                          values: [last(start_price)]
                                          filter: isin='DE000A0KRJS4'
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: xetra
                            """)
                    .returns("day\tisin\tlast\n");
        });
    }

