    @Test
    public void testOrderByPropagation() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE contacts (_id SYMBOL, customName STRING, name SYMBOL, email STRING, country_name SYMBOL, country_code SYMBOL, city SYMBOL, region SYMBOL, emoji_flag STRING, latitude DOUBLE, longitude DOUBLE, isNotReal SYMBOL, notRealType SYMBOL, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            execute("CREATE TABLE contact_events (contactId SYMBOL, groupId SYMBOL, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            assertQuery(
                    """
                            WITH\s
                            contactlist AS (SELECT * FROM contacts LATEST ON timestamp PARTITION BY _id ORDER BY timestamp),
                            eventlist AS (SELECT * FROM contact_events LATEST ON timestamp PARTITION BY contactId ORDER BY timestamp),
                            C AS (
                                SELECT DISTINCT contactId FROM eventlist WHERE groupId = 'qIqlX6qESMtTQXikQA46'
                                EXCEPT
                                SELECT _id as contactId FROM contactlist WHERE notRealType = 'bot'
                            )
                              SELECT\s
                                C.contactId as id,\s
                                contactlist.customName,
                                contactlist.name,
                                contactlist.email,
                                contactlist.country_name,
                                contactlist.country_code,
                                contactlist.city,
                                contactlist.region,
                                contactlist.emoji_flag,
                                contactlist.latitude,
                                contactlist.longitude,
                                contactlist.isNotReal,
                                contactlist.notRealType
                              FROM C\s
                              JOIN contactlist ON contactlist._id = C.contactId
                              ORDER BY timestamp DESC
                            """
            )
                    .noLeakCheck()
                    .withPlan("""
                            SelectedRecord
                                Encode sort
                                  keys: [timestamp desc]
                                    SelectedRecord
                                        Hash Join Light
                                          condition: contactlist._id=C.contactId
                                          symbolKeyJoin: true
                                            Except
                                                GroupBy vectorized: false
                                                  keys: [contactId]
                                                    Filter filter: groupId='qIqlX6qESMtTQXikQA46'
                                                        LatestByDeferredListValuesFiltered
                                                            Frame backward scan on: contact_events
                                                Hash
                                                    SelectedRecord
                                                        Filter filter: notRealType='bot'
                                                            LatestByDeferredListValuesFiltered
                                                                Frame backward scan on: contacts
                                            Hash
                                                LatestByDeferredListValuesFiltered
                                                    Frame backward scan on: contacts
                            """)
                    .returns("id\tcustomName\tname\temail\tcountry_name\tcountry_code\tcity\tregion\temoji_flag\tlatitude\tlongitude\tisNotReal\tnotRealType\n");
        });
    }

