    @Test
    public void testOrderByWithLatestBy() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE trips (id INT, vendor_id SYMBOL, pickup_datetime TIMESTAMP) TIMESTAMP(pickup_datetime)");
            assertQuery(
                    """
                            SELECT * FROM trips
                            WHERE pickup_datetime < '2009-01-01T00:02:19.000000Z'
                            latest on pickup_datetime partition by vendor_id
                            ORDER BY pickup_datetime"""
            )
                    .noLeakCheck()
                    .timestamp("pickup_datetime")
                    .withPlan("""
                            LatestByDeferredListValuesFiltered
                                Interval backward scan on: trips
                                  intervals: [("MIN","2009-01-01T00:02:18.999999Z")]
                            """)
                    .returns("id\tvendor_id\tpickup_datetime\n");
        });
    }

