    @Test
    public void testOrderByWithSampleBy() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE tab (a INT, b INT, t TIMESTAMP)");
            assertQuery("select a, sum(b) from (tab order by t) timestamp(t) sample by 2m align to first observation order by a")
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort
                              keys: [a]
                                Sample By
                                  keys: [a]
                                  values: [sum(b)]
                                    Encode sort light
                                      keys: [t]
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: tab
                            """)
                    .returns("a\tsum\n");
            assertQuery("select a, sum(b) from (tab order by t) timestamp(t) sample by 2m order by a")
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort light
                              keys: [a]
                                SelectedRecord
                                    GroupBy vectorized: false
                                      keys: [a,t]
                                      values: [sum(b)]
                                        Encode sort light
                                          keys: [t]
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: tab
                            """)
                    .returns("a\tsum\n");
            assertQuery("select a, sum(b) from (tab order by t) timestamp(t) sample by 2m align to calendar order by a")
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort light
                              keys: [a]
                                SelectedRecord
                                    GroupBy vectorized: false
                                      keys: [a,t]
                                      values: [sum(b)]
                                        Encode sort light
                                          keys: [t]
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: tab
                            """)
                    .returns("a\tsum\n");
            assertQuery("select a, sum(b) from (tab order by t) timestamp(t) sample by 2m align to calendar time zone 'Europe/Paris' order by a")
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort light
                              keys: [a]
                                SelectedRecord
                                    GroupBy vectorized: false
                                      keys: [a,t]
                                      values: [sum(b)]
                                        Encode sort light
                                          keys: [t]
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: tab
                            """)
                    .returns("a\tsum\n");
            assertQuery("select a, sum(b) from (tab order by t) timestamp(t) sample by 2m align to calendar time zone 'Europe/Paris' order by 1 desc")
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort light
                              keys: [a desc]
                                SelectedRecord
                                    GroupBy vectorized: false
                                      keys: [a,t]
                                      values: [sum(b)]
                                        Encode sort light
                                          keys: [t]
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: tab
                            """)
                    .returns("a\tsum\n");
            assertQuery("select 10*a as a10, sum(b) from (tab order by t) timestamp(t) sample by 2m align to calendar time zone 'Europe/Paris' order by a10")
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort light
                              keys: [a10]
                                SelectedRecord
                                    GroupBy vectorized: false
                                      keys: [a10,t]
                                      values: [sum(b)]
                                        Encode sort light
                                          keys: [t]
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: tab
                            """)
                    .returns("a10\tsum\n");
            assertQuery("select a as a0, sum(b) from (tab order by t) timestamp(t) sample by 2m align to calendar time zone 'Europe/Paris' order by 10*a desc, 1 asc")
                    .noLeakCheck()
                    .withPlan("""
                            SelectedRecord
                                Encode sort light
                                  keys: [column desc, a0]
                                    GroupBy vectorized: false
                                      keys: [a0,t,column]
                                      values: [sum(b)]
                                        Encode sort light
                                          keys: [t]
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: tab
                            """)
                    .returns("a0\tsum\n");
        });
    }

