    @Test
    public void testOuterJoin() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE a (x INT)");
            execute("CREATE TABLE b (x INT)");
            final String query = "select a.x from a a #OUTER_JOIN_TYPE join b on b.x = a.x";
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "left"))
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Hash Left Outer Join Light
                                  condition: b.x=a.x
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: a
                                    Hash
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: b
                            """)
                    .returns("x\n");
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "right"))
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Hash Right Outer Join Light
                                  condition: b.x=a.x
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: a
                                    Hash
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: b
                            """)
                    .returns("x\n");
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "full"))
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            SelectedRecord
                                Hash Full Outer Join Light
                                  condition: b.x=a.x
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: a
                                    Hash
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: b
                            """)
                    .returns("x\n");
        });
    }

