    @Test
    public void testPGTableListQuery() throws Exception {
        assertMemoryLeak(() -> {
            final String query = """
                    SELECT n.nspname                              as "Schema",
                           c.relname                              as "Name",
                           CASE c.relkind
                               WHEN 'r' THEN 'table'
                               WHEN 'v' THEN 'view'
                               WHEN 'm' THEN 'materialized view'
                               WHEN 'i' THEN 'index'
                               WHEN 'S' THEN 'sequence'
                               WHEN 's' THEN 'special'
                               WHEN 'f' THEN 'foreign table'
                               WHEN 'p' THEN 'table'
                               WHEN 'I' THEN 'index' END          as "Type",
                           pg_catalog.pg_get_userbyid(c.relowner) as "Owner"
                    FROM pg_catalog.pg_class c
                             #OUTER_JOIN_TYPE join pg_catalog.pg_namespace n ON n.oid = c.relnamespace
                    WHERE c.relkind IN ('r', 'p', 'v', 'm', 'S', 'f', '')
                      AND n.nspname != 'pg_catalog'
                      AND n.nspname != 'information_schema'
                      AND n.nspname !~ '^pg_toast'
                      AND pg_catalog.pg_table_is_visible(c.oid)
                    ORDER BY 1, 2""";
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "left"))
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort
                              keys: [Schema, Name]
                                VirtualRecord
                                  functions: [n.nspname,c.relname,case(['table','view','materialized view','index','sequence','special','foreign table','table','index',null,c.relkind]),'public']
                                    Filter filter: (n.nspname!='pg_catalog' and n.nspname!='information_schema' and n.nspname !~ ^pg_toast)
                                        Hash Left Outer Join
                                          condition: n.oid=c.relnamespace
                                            Filter filter: relkind in [114,112,118,109,83,102,0]
                                                pg_class
                                            Hash
                                                GenericRecord
                            """)
                    .returns("Schema\tName\tType\tOwner\n");
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "right"))
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort
                              keys: [Schema, Name]
                                VirtualRecord
                                  functions: [n.nspname,c.relname,case(['table','view','materialized view','index','sequence','special','foreign table','table','index',null,c.relkind]),'public']
                                    Filter filter: (c.relkind in [114,112,118,109,83,102,0] and n.nspname!='pg_catalog' and n.nspname!='information_schema' and n.nspname !~ ^pg_toast)
                                        Hash Right Outer Join
                                          condition: n.oid=c.relnamespace
                                            pg_class
                                            Hash
                                                GenericRecord
                            """)
                    .returns("""
                            Schema\tName\tType\tOwner
                            public\t\t\tpublic
                            """);
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "full"))
                    .noLeakCheck()
                    .withPlan("""
                            Encode sort
                              keys: [Schema, Name]
                                VirtualRecord
                                  functions: [n.nspname,c.relname,case(['table','view','materialized view','index','sequence','special','foreign table','table','index',null,c.relkind]),'public']
                                    Filter filter: (c.relkind in [114,112,118,109,83,102,0] and n.nspname!='pg_catalog' and n.nspname!='information_schema' and n.nspname !~ ^pg_toast)
                                        Hash Full Outer Join
                                          condition: n.oid=c.relnamespace
                                            pg_class
                                            Hash
                                                GenericRecord
                            """)
                    .returns("""
                            Schema\tName\tType\tOwner
                            public\t\t\tpublic
                            """);
        });
    }

    @Test
    public void testPartitionByOrderByAcceptsAsc() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE weather (ts TIMESTAMP, temperature FLOAT)");
            assertQuery(
                    """
                            select ts, temperature from
                            (
                              select ts, temperature,
                                     row_number() over (partition by timestamp_floor('y', ts) order by temperature asc) rid
                              from weather
                            ) inq
                            where rid = 0
                            order by ts
                            """
            )
                    .noLeakCheck()
                    .timestamp("ts")
                    .withPlan("""
                            Encode sort light
                              keys: [ts]
                                SelectedRecord
                                    Filter filter: rid=0
                                        CachedWindowLight
                                          orderedFunctions: [[temperature] => [row_number() over (partition by [timestamp_floor('year',ts)])]]
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: weather
                            """)
                    .returns("ts\ttemperature\n");
        });
    }

