    @Test
    public void testPipeConcatInJoin() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE tab (x STRING)");
            execute("CREATE TABLE bap (y STRING)");
            assertQuery("select 1, x from tab join bap on tab.x || '1' = '2' || substring(bap.y, 0, 5)")
                    .noLeakCheck()
                    .noRandomAccess()
                    .withPlan("""
                            VirtualRecord
                              functions: [1,tab.x]
                                Filter filter: concat([tab.x,'1'])=concat(['2',substring(bap.y,0,5)])
                                    Cross Join
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: tab
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: bap
                            """)
                    .returns("1\tx\n");
        });
    }

