    @Test
    public void testQuotedTableAliasFollowedByStar() throws Exception {
        assertMemoryLeak(() -> {
            assertQuery("select foo.* from long_sequence(1) as foo")
                    .noLeakCheck()
                    .expectSize()
                    .returns("x\n1\n");
            assertQuery("select 'foo'.* from long_sequence(1) as foo")
                    .noLeakCheck()
                    .expectSize()
                    .returns("x\n1\n");
            assertQuery("select foo.* from long_sequence(1) as 'foo'")
                    .noLeakCheck()
                    .expectSize()
                    .returns("x\n1\n");
            assertQuery("select 'foo'.* from long_sequence(1) as 'foo'")
                    .noLeakCheck()
                    .expectSize()
                    .returns("x\n1\n");
            assertQuery("select \"foo\".* from long_sequence(1) as \"foo\"")
                    .noLeakCheck()
                    .expectSize()
                    .returns("x\n1\n");
            assertQuery("select \"foo\".* from long_sequence(1) as 'foo'")
                    .noLeakCheck()
                    .expectSize()
                    .returns("x\n1\n");
            assertQuery("select 'foo'.* from long_sequence(1) as \"foo\"")
                    .noLeakCheck()
                    .expectSize()
                    .returns("x\n1\n");
            assertQuery("select 'foo'.\"*\" from long_sequence(1) as \"foo\"")
                    .noLeakCheck()
                    .expectSize()
                    .returns("x\n1\n");
            assertQuery("select 'foo'.'*' from long_sequence(1) as \"foo\"")
                    .noLeakCheck()
                    .expectSize()
                    .returns("x\n1\n");
            assertQuery("select \"foo.*\" from long_sequence(1) as \"foo\"")
                    .noLeakCheck()
                    .expectSize()
                    .returns("x\n1\n");
            // the alias itself contains double quotes. should this be allowed at all?
            assertQuery("select \\\"foo\\\".* from long_sequence(1) as \\\"foo\\\"")
                    .noLeakCheck()
                    .expectSize()
                    .returns("x\n1\n");
        });
    }

