    @Test
    public void testSampleByUnionAll() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE x (a DOUBLE, b SYMBOL, k TIMESTAMP, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            assertQuery("select b, sum(a), k k1, k from x y sample by 3h align to calendar" +
                    " union all " +
                    "select b, sum(a), k k1, k from x y sample by 3h align to calendar")
                    .noLeakCheck()
                    .assertsPlan("""
                            UnionSymbolCast
                              functions: [b::symbol,sum,k1,k]
                                Union All
                                    SelectedRecord
                                        Encode sort light
                                          keys: [timestamp]
                                            SelectedRecord
                                                Async Group By workers: 1
                                                  keys: [b,k1,timestamp]
                                                  keyFunctions: [timestamp_floor_utc('3h',timestamp)]
                                                  values: [sum(a)]
                                                  filter: null
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: x
                                    SelectedRecord
                                        Encode sort light
                                          keys: [timestamp]
                                            SelectedRecord
                                                Async Group By workers: 1
                                                  keys: [b,k1,timestamp]
                                                  keyFunctions: [timestamp_floor_utc('3h',timestamp)]
                                                  values: [sum(a)]
                                                  filter: null
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: x
                            """);
            assertQuery("select b, sum(a), k k1, k from x y sample by 3h" +
                    " union all " +
                    "select b, sum(a), k k1, k from x y sample by 3h")
                    .noLeakCheck()
                    .assertsPlan("""
                            UnionSymbolCast
                              functions: [b::symbol,sum,k1,k]
                                Union All
                                    SelectedRecord
                                        Encode sort light
                                          keys: [timestamp]
                                            SelectedRecord
                                                Async Group By workers: 1
                                                  keys: [b,k1,timestamp]
                                                  keyFunctions: [timestamp_floor_utc('3h',timestamp)]
                                                  values: [sum(a)]
                                                  filter: null
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: x
                                    SelectedRecord
                                        Encode sort light
                                          keys: [timestamp]
                                            SelectedRecord
                                                Async Group By workers: 1
                                                  keys: [b,k1,timestamp]
                                                  keyFunctions: [timestamp_floor_utc('3h',timestamp)]
                                                  values: [sum(a)]
                                                  filter: null
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: x
                            """);
            assertQuery("select b, sum(a), k k1, k from x y sample by 3h align to first observation" +
                    " union all " +
                    "select b, sum(a), k k1, k from x y sample by 3h align to first observation")
                    .noLeakCheck()
                    .assertsPlan("""
                            UnionSymbolCast
                              functions: [b::symbol,sum,k1,k]
                                Union All
                                    SelectedRecord
                                        Sample By
                                          keys: [b,k1]
                                          values: [sum(a)]
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: x
                                    SelectedRecord
                                        Sample By
                                          keys: [b,k1]
                                          values: [sum(a)]
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: x
                            """);
        });
    }

