    public void testSelectAfterOrderBy() throws Exception {
        final String query = """
                select distinct Schema from\s
                (SELECT n.nspname                              as "Schema",
                       c.relname                              as "Name",
                       CASE c.relkind
                           WHEN 'r' THEN 'table'
                           WHEN 'v' THEN 'view'
                           WHEN 'm' THEN 'materialized view'
                           WHEN 'i' THEN 'index'
                           WHEN 'S' THEN 'sequence'
                           WHEN 's' THEN 'special'
                           WHEN 'f' THEN 'foreign table'
                           WHEN 'p' THEN 'table'
                           WHEN 'I' THEN 'index' END          as "Type",
                       pg_catalog.pg_get_userbyid(c.relowner) as "Owner"
                FROM pg_catalog.pg_class c
                         #OUTER_JOIN_TYPE join pg_catalog.pg_namespace n ON n.oid = c.relnamespace
                WHERE c.relkind IN ('r', 'p', 'v', 'm', 'S', 'f', '')
                  AND n.nspname != 'pg_catalog'
                  AND n.nspname != 'information_schema'
                  AND n.nspname !~ '^pg_toast'
                  AND pg_catalog.pg_table_is_visible(c.oid)
                ORDER BY 1, 2);
                """;
        assertMemoryLeak(() -> {
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "left"))
                    .noLeakCheck()
                    .assertsPlan("""
                            GroupBy vectorized: false
                              keys: [Schema]
                                Encode sort
                                  keys: [Schema, Name]
                                    VirtualRecord
                                      functions: [n.nspname,c.relname]
                                        Filter filter: (n.nspname!='pg_catalog' and n.nspname!='information_schema' and n.nspname !~ ^pg_toast)
                                            Hash Left Outer Join
                                              condition: n.oid=c.relnamespace
                                                Filter filter: relkind in [114,112,118,109,83,102,0]
                                                    pg_class
                                                Hash
                                                    GenericRecord
                            """);
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "right"))
                    .noLeakCheck()
                    .assertsPlan("""
                            GroupBy vectorized: false
                              keys: [Schema]
                                Encode sort
                                  keys: [Schema, Name]
                                    VirtualRecord
                                      functions: [n.nspname,c.relname]
                                        Filter filter: (c.relkind in [114,112,118,109,83,102,0] and n.nspname!='pg_catalog' and n.nspname!='information_schema' and n.nspname !~ ^pg_toast)
                                            Hash Right Outer Join
                                              condition: n.oid=c.relnamespace
                                                pg_class
                                                Hash
                                                    GenericRecord
                            """);
            assertQuery(query.replace("#OUTER_JOIN_TYPE", "full"))
                    .noLeakCheck()
                    .assertsPlan("""
                            GroupBy vectorized: false
                              keys: [Schema]
                                Encode sort
                                  keys: [Schema, Name]
                                    VirtualRecord
                                      functions: [n.nspname,c.relname]
                                        Filter filter: (c.relkind in [114,112,118,109,83,102,0] and n.nspname!='pg_catalog' and n.nspname!='information_schema' and n.nspname !~ ^pg_toast)
                                            Hash Full Outer Join
                                              condition: n.oid=c.relnamespace
                                                pg_class
                                                Hash
                                                    GenericRecord
                            """);
        });
    }

