    @Test
    public void testSpliceJoinSubQuery() throws Exception {
        // execution order must be (src: SQL Server)
        //        1. FROM
        //        2. ON
        //        3. JOIN
        //        4. WHERE
        //        5. GROUP BY
        //        6. WITH CUBE or WITH ROLLUP
        //        7. HAVING
        //        8. SELECT
        //        9. DISTINCT
        //        10. ORDER BY
        //        11. TOP
        //
        // which means "where" clause for "e" table has to be explicitly as post-join-where
        assertMemoryLeak(() -> {
            execute("CREATE TABLE customers (customerId SYMBOL, ts TIMESTAMP) TIMESTAMP(ts)");
            execute("CREATE TABLE employees (employeeId STRING, lastName STRING, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            execute("CREATE TABLE orders (customerId SYMBOL, ts TIMESTAMP) TIMESTAMP(ts)");
            assertQuery("customers c" +
                    " splice join (select '1' blah, lastName, employeeId, timestamp from employees order by timestamp) e on c.customerId = e.employeeId" +
                    " join orders o on c.customerId = o.customerId where e.lastName = 'x' and e.blah = 'y'")
                    .noLeakCheck()
                    .assertsPlan("""
                            SelectedRecord
                                Hash Join Light
                                  condition: o.customerId=c.customerId
                                  symbolKeyJoin: true
                                    Filter filter: (e.lastName='x' and e.blah=y)
                                        Splice Join
                                          condition: e.employeeId=c.customerId
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: customers
                                            VirtualRecord
                                              functions: ['1',lastName,employeeId,timestamp]
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: employees
                                    Hash
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: orders
                            """);
        });
    }

