    @Test
    public void testTimestampPredicateNestedSubqueriesMultipleOffsetLevels() throws Exception {
        // Nested subqueries with multiple dateadd levels
        // Both levels should have ts_offset:
        // - Inner: ts_offset ('h', 1, 0) for dateadd('h', -1, timestamp)
        // - Outer: ts_offset ('d', 1, 0) for dateadd('d', -1, ts1) where ts1 is the inner timestamp column
        assertMemoryLeak(() -> {
            execute("CREATE TABLE trades (price DOUBLE, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            assertQuery("SELECT * FROM ((SELECT dateadd('d', -1, ts1) as ts2, price FROM ((SELECT dateadd('h', -1, timestamp) as ts1, price FROM trades) timestamp (ts1))) timestamp (ts2))")
                    .noLeakCheck()
                    .assertsPlan("""
                            VirtualRecord
                              functions: [dateadd('d',-1,ts1),price]
                                VirtualRecord
                                  functions: [dateadd('h',-1,timestamp),price]
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: trades
                            """);
        });
    }

    @Test
    public void testTimestampPredicateNestedSubqueriesWithOuterPredicate() throws Exception {
        // Nested subqueries with predicate on outermost level
        // Predicate is pushed through ALL offset levels to the base table
        // The and_offset wrappers chain: and_offset(and_offset(original, 'd', 1), 'h', 1)
        assertMemoryLeak(() -> {
            execute("CREATE TABLE trades (price DOUBLE, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            assertQuery("SELECT * FROM ((SELECT dateadd('d', -1, ts1) as ts2, price FROM ((SELECT dateadd('h', -1, timestamp) as ts1, price FROM trades) timestamp (ts1))) timestamp (ts2)) WHERE ts2 in '2022'")
                    .noLeakCheck()
                    .assertsPlan("""
                            VirtualRecord
                              functions: [dateadd('d',-1,ts1),price]
                                VirtualRecord
                                  functions: [dateadd('h',-1,timestamp),price]
                                    PageFrame
                                        Row forward scan
                                        Interval forward scan on: trades
                                          intervals: [("2022-01-02T01:00:00.000000Z","2023-01-02T00:59:59.999999Z")]
                            """);
        });
    }

