    @Test
    public void testTooManyColumnsEdgeInOrderBy() throws Exception {
        assertMemoryLeak(() -> {
            StringBuilder ddl = new StringBuilder("CREATE TABLE x (");
            StringBuilder query = new StringBuilder("x order by ");
            StringBuilder keys = new StringBuilder("keys: [");
            for (int i = 0; i < SqlParser.MAX_ORDER_BY_COLUMNS - 1; i++) {
                if (i > 0) {
                    ddl.append(", ");
                    query.append(',');
                    keys.append(", ");
                }
                ddl.append('f').append(i).append(" INT");
                query.append('f').append(i);
                keys.append('f').append(i);
            }
            ddl.append(')');
            keys.append(']');
            execute(ddl);
            assertQuery(query)
                    .noLeakCheck()
                    .assertsPlanContaining("Encode sort light", keys);
        });
    }

    @Test
    public void testTooManyColumnsInOrderBy() throws Exception {
        assertMemoryLeak(() -> {
            StringBuilder b = new StringBuilder();
            b.append("x order by ");
            for (int i = 0; i < SqlParser.MAX_ORDER_BY_COLUMNS; i++) {
                if (i > 0) {
                    b.append(',');
                }
                b.append('f').append(i);
            }
            try {
                select(b).close();
                Assert.fail();
            } catch (SqlException e) {
                TestUtils.assertEquals("Too many columns", e.getFlyweightMessage());
            }
        });
    }

