    @Test
    public void testUnexpectedDotInCaseStatement() throws Exception {
        assertSyntaxError("SELECT CASE WHEN . THEN 1 ELSE 1 END", 17, "unexpected dot");
        assertSyntaxError("SELECT CASE WHEN True THEN . ELSE 1 END", 27, "unexpected dot");
        assertSyntaxError("SELECT CASE WHEN True THEN 1 ELSE . END", 34, "unexpected dot");

        assertMemoryLeak(() -> {
            assertQuery("SELECT CASE WHEN True THEN 1.0f ELSE 1 END")
                    .noLeakCheck()
                    .expectSize()
                    .returns("case\n1.0\n");
            assertQuery("SELECT CASE WHEN True THEN 'a.b' ELSE '1' END")
                    .noLeakCheck()
                    .expectSize()
                    .returns("case\na.b\n");
            assertQuery("SELECT CASE WHEN True THEN \"a.x\" ELSE 1 END from long_sequence(1) a")
                    .noLeakCheck()
                    .expectSize()
                    .returns("case\n1\n");
            assertQuery("SELECT CASE WHEN True THEN a.x ELSE 1 END from long_sequence(1) a")
                    .noLeakCheck()
                    .expectSize()
                    .returns("case\n1\n");
        });
    }

