    @Test
    public void testUnionJoinReorder3() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE orders (orderId INT)");
            execute("CREATE TABLE customers (customerId INT)");
            execute("CREATE TABLE orderDetails (orderId INT, productId INT)");
            execute("CREATE TABLE products (productId INT, supplier INT)");
            execute("CREATE TABLE suppliers (supplier INT)");
            execute("CREATE TABLE shippers (shipper INT)");
            assertQuery("select 1, 2, 3, 4, 5, 6, 7, 8 from long_sequence(1) union orders left join customers on 1=1 join shippers on shippers.shipper = orders.orderId join orderDetails d on d.orderId = orders.orderId and d.productId = shippers.shipper join suppliers on products.supplier = suppliers.supplier join products on d.productId = products.productId where d.productId = d.orderId")
                    .noLeakCheck()
                    .assertsPlan("""
                            Union
                                VirtualRecord
                                  functions: [1,2,3,4,5,6,7,8]
                                    long_sequence count: 1
                                SelectedRecord
                                    Nested Loop Left Join
                                      filter: true
                                        Hash Join Light
                                          condition: suppliers.supplier=products.supplier
                                            Hash Join Light
                                              condition: products.productId=d.productId
                                                Hash Join Light
                                                  condition: d.productId=shippers.shipper and d.orderId=orders.orderId
                                                    Hash Join Light
                                                      condition: shippers.shipper=orders.orderId
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: orders
                                                        Hash
                                                            PageFrame
                                                                Row forward scan
                                                                Frame forward scan on: shippers
                                                    Hash
                                                        Async JIT Filter workers: 1
                                                          filter: productId=orderId
                                                            PageFrame
                                                                Row forward scan
                                                                Frame forward scan on: orderDetails
                                                Hash
                                                    PageFrame
                                                        Row forward scan
                                                        Frame forward scan on: products
                                            Hash
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: suppliers
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: customers
                            """);
            assertQuery("select 1, 2, 3, 4, 5, 6, 7, 8 from long_sequence(1) union orders right join customers on 1=1 join shippers on shippers.shipper = orders.orderId join orderDetails d on d.orderId = orders.orderId and d.productId = shippers.shipper join suppliers on products.supplier = suppliers.supplier join products on d.productId = products.productId where d.productId = d.orderId")
                    .noLeakCheck()
                    .assertsPlan("""
                            Union
                                VirtualRecord
                                  functions: [1,2,3,4,5,6,7,8]
                                    long_sequence count: 1
                                SelectedRecord
                                    Hash Join Light
                                      condition: suppliers.supplier=products.supplier
                                        Hash Join Light
                                          condition: products.productId=d.productId
                                            Hash Join Light
                                              condition: d.productId=shippers.shipper and d.orderId=orders.orderId
                                                Hash Join Light
                                                  condition: shippers.shipper=orders.orderId
                                                    Nested Loop Right Join
                                                      filter: true
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: orders
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: customers
                                                    Hash
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: shippers
                                                Hash
                                                    Async JIT Filter workers: 1
                                                      filter: productId=orderId
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: orderDetails
                                            Hash
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: products
                                        Hash
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: suppliers
                            """);
            assertQuery("select 1, 2, 3, 4, 5, 6, 7, 8 from long_sequence(1) union orders full join customers on 1=1 join shippers on shippers.shipper = orders.orderId join orderDetails d on d.orderId = orders.orderId and d.productId = shippers.shipper join suppliers on products.supplier = suppliers.supplier join products on d.productId = products.productId where d.productId = d.orderId")
                    .noLeakCheck()
                    .assertsPlan("""
                            Union
                                VirtualRecord
                                  functions: [1,2,3,4,5,6,7,8]
                                    long_sequence count: 1
                                SelectedRecord
                                    Hash Join Light
                                      condition: suppliers.supplier=products.supplier
                                        Hash Join Light
                                          condition: products.productId=d.productId
                                            Hash Join Light
                                              condition: d.productId=shippers.shipper and d.orderId=orders.orderId
                                                Hash Join Light
                                                  condition: shippers.shipper=orders.orderId
                                                    Nested Loop Full Join
                                                      filter: true
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: orders
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: customers
                                                    Hash
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: shippers
                                                Hash
                                                    Async JIT Filter workers: 1
                                                      filter: productId=orderId
                                                        PageFrame
                                                            Row forward scan
                                                            Frame forward scan on: orderDetails
                                            Hash
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: products
                                        Hash
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: suppliers
                            """);
        });
    }

