    @Test
    public void testVWAP() throws Exception {
        // Window functions with OVER clause should be preserved as window functions, not converted to GROUP BY
        assertMemoryLeak(() -> {
            execute("CREATE TABLE trades (price DOUBLE, volume DOUBLE, symbol SYMBOL, timestamp TIMESTAMP) TIMESTAMP(timestamp)");
            assertQuery("""
                    SELECT
                            timestamp,
                            symbol,
                            sum(price * volume) OVER (
                                PARTITION BY symbol, timestamp
                                ORDER BY timestamp
                            ) / sum(volume) OVER (
                                PARTITION BY symbol, timestamp
                                ORDER BY timestamp
                            ) AS vwap_daily
                        FROM trades
                        WHERE timestamp > dateadd('d', -1, '2024-01-02'::TIMESTAMP)
                    """)
                    .noLeakCheck()
                    .assertsPlan("""
                            VirtualRecord
                              functions: [timestamp,symbol,sum/sum1]
                                Window
                                  functions: [sum(price*volume) over (partition by [symbol,timestamp] rows between unbounded preceding and current row),sum(volume) over (partition by [symbol,timestamp] rows between unbounded preceding and current row)]
                                    PageFrame
                                        Row forward scan
                                        Interval forward scan on: trades
                                          intervals: [("2024-01-01T00:00:00.000001Z","MAX")]
                            """);
        });
    }

