    @Test
    public void testWhereNotSelectedColumn() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE customers (customerId INT, weight DOUBLE)");
            execute("CREATE TABLE orders (customerId INT, x INT)");
            assertQuery("customers c left join (orders o where o.x = 10) o on c.customerId = o.customerId where c.weight = 100")
                    .noLeakCheck()
                    .assertsPlan("""
                            SelectedRecord
                                Hash Left Outer Join Light
                                  condition: o.customerId=c.customerId
                                    Async JIT Filter workers: 1
                                      filter: weight=100
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: customers
                                    Hash
                                        Async JIT Filter workers: 1
                                          filter: x=10
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: orders
                            """);
            assertQuery("customers c right join (orders o where o.x = 10) o on c.customerId = o.customerId where c.weight = 100")
                    .noLeakCheck()
                    .assertsPlan("""
                            SelectedRecord
                                Filter filter: c.weight=100
                                    Hash Right Outer Join Light
                                      condition: o.customerId=c.customerId
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: customers
                                        Hash
                                            Async JIT Filter workers: 1
                                              filter: x=10
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: orders
                            """);
            assertQuery("customers c full join (orders o where o.x = 10) o on c.customerId = o.customerId where c.weight = 100")
                    .noLeakCheck()
                    .assertsPlan("""
                            SelectedRecord
                                Filter filter: c.weight=100
                                    Hash Full Outer Join Light
                                      condition: o.customerId=c.customerId
                                        PageFrame
                                            Row forward scan
                                            Frame forward scan on: customers
                                        Hash
                                            Async JIT Filter workers: 1
                                              filter: x=10
                                                PageFrame
                                                    Row forward scan
                                                    Frame forward scan on: orders
                            """);
        });
    }

    @Test
    public void testWindowFunctionArithmeticInsideFunction() throws Exception {
        // Two window functions in arithmetic expression inside abs() - should be allowed
        // because the window functions are operands of an expression, not direct arguments
        assertMemoryLeak(() -> {
            execute("CREATE TABLE trades (symbol SYMBOL, amount DOUBLE, ts TIMESTAMP) TIMESTAMP(ts)");
            assertQuery("select *, abs(ksum(amount) over() - sum(amount) over()) from trades where symbol = 'sym1' limit 100000")
                    .noLeakCheck()
                    .assertsPlan("""
                            Limit value: 100000 skip-rows-max: 0 take-rows-max: 100000
                                VirtualRecord
                                  functions: [symbol,amount,ts,abs(ksum-sum)]
                                    CachedWindowLight
                                      unorderedFunctions: [ksum(amount) over (),sum(amount) over ()]
                                        Async JIT Filter workers: 1
                                          filter: symbol='sym1'
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: trades
                            """);
        });
    }

    @Test
    public void testWindowFunctionArithmeticTwoWindows() throws Exception {
        // Two window functions in arithmetic operation - sum() is both aggregate and window function name,
        // but with OVER clause it should be treated as window function, not GROUP BY aggregate
        assertMemoryLeak(() -> {
            execute("CREATE TABLE x (id LONG, ts TIMESTAMP) TIMESTAMP(ts)");
            assertQuery("SELECT sum(id) OVER (ORDER BY ts) - lag(id) OVER (ORDER BY ts) AS id_diff FROM x")
                    .noLeakCheck()
                    .assertsPlan("""
                            VirtualRecord
                              functions: [sum-lag]
                                Window
                                  functions: [sum(id) over (rows between unbounded preceding and current row),lag(id, 1, NULL) over ()]
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: x
                            """);
        });
    }

    @Test
    public void testWindowFunctionAsArgumentToWindowFunction() throws Exception {
        // Window function as argument to another window function
        // sum(row_number() OVER ()) OVER ()
        // The inner window function is extracted to a separate select-window layer
        // The outer sum references the inner window column by alias (row_number)
        // The inner window model has both topDownColumns and bottomUpColumns for column propagation
        assertMemoryLeak(() -> {
            execute("CREATE TABLE x (ts TIMESTAMP) TIMESTAMP(ts)");
            assertQuery("SELECT sum(row_number() OVER ()) OVER () FROM x")
                    .noLeakCheck()
                    .assertsPlan("""
                            CachedWindow
                              unorderedFunctions: [sum(row_number) over ()]
                                Window
                                  functions: [row_number()]
                                    PageFrame
                                        Row forward scan
                                        Frame forward scan on: x
                            """);
        });
    }

