    @Test
    public void testWindowOrderDirection() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE xyz (a INT, b INT, c INT, x INT, y INT, z INT, ts TIMESTAMP) TIMESTAMP(ts)");
            assertQuery("select a,b, lag(c) over (partition by b order by ts desc, x asc, y) my from xyz")
                    .noLeakCheck()
                    .assertsPlan("""
                            CachedWindowLight
                              orderedFunctions: [[ts desc, x, y] => [lag(c, 1, NULL) over (partition by [b])]]
                                PageFrame
                                    Row forward scan
                                    Frame forward scan on: xyz
                            """);
        });
    }

