    @Test
    public void testWithWindowFunctionRankAndOrderByAlias() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE trades (symbol SYMBOL, price DOUBLE)");
            assertQuery("""
                    with d as (select symbol, price, count() from trades)
                    select *
                          , 100 * (rank() over(partition by symbol order by price)) as rank1
                    from d
                    where symbol = 'EURUSD'
                    order by rank1""")
                    .noLeakCheck()
                    .assertsPlan("""
                            Encode sort light
                              keys: [rank1]
                                VirtualRecord
                                  functions: [symbol,price,count,100*rank]
                                    CachedWindowLight
                                      orderedFunctions: [[price] => [rank() over (partition by [symbol])]]
                                        Async JIT Group By workers: 1
                                          keys: [symbol,price]
                                          values: [count(*)]
                                          filter: symbol='EURUSD'
                                            PageFrame
                                                Row forward scan
                                                Frame forward scan on: trades
                            """);
        });
    }

